void main() async { WidgetsFlutterBinding.ensureInitialized(); await Store.instance.db; runApp(const PocketLedger()); }

class Txn {
  final String id,title,category,type,account,note; final double amount; final DateTime date;
  Txn({required this.id,required this.title,required this.category,required this.type,required this.amount,required this.date,this.account='Cash',this.note=''});
  Map<String,Object?> map()=>{'id':id,'title':title,'category':category,'type':type,'amount':amount,'date':date.toIso8601String(),'account':account,'note':note};
  factory Txn.from(Map<String,Object?> m)=>Txn(id:m['id'] as String,title:m['title'] as String,category:m['category'] as String,type:m['type'] as String,amount:(m['amount'] as num).toDouble(),date:DateTime.parse(m['date'] as String),account:(m['account'] as String?)??'Cash',note:(m['note'] as String?)??'');
}
class Store {
  Store._(); static final instance=Store._(); Database? _db;
  Future<Database> get db async { if(_db!=null)return _db!; final path=p.join(await getDatabasesPath(),'pocket_ledger.db'); _db=await openDatabase(path,version:1,onCreate:(d,v)async{await d.execute('CREATE TABLE transactions(id TEXT PRIMARY KEY,title TEXT NOT NULL,category TEXT NOT NULL,type TEXT NOT NULL,amount REAL NOT NULL,date TEXT NOT NULL,account TEXT NOT NULL,note TEXT NOT NULL)');await d.execute('CREATE INDEX txn_date ON transactions(date)');}); return _db!; }
  Future<List<Txn>> all() async => (await (await db).query('transactions',orderBy:'date DESC')).map(Txn.from).toList();
  Future<void> save(Txn t) async {await (await db).insert('transactions',t.map(),conflictAlgorithm:ConflictAlgorithm.replace);}
  Future<void> remove(String id) async {await (await db).delete('transactions',where:'id=?',whereArgs:[id]);}
}
class PocketLedger extends StatelessWidget {const PocketLedger({super.key}); @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'PocketLedger',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:blue),scaffoldBackgroundColor:const Color(0xFFF5F7FB),appBarTheme:const AppBarTheme(backgroundColor:Color(0xFFF5F7FB),foregroundColor:navy,elevation:0),cardTheme:CardThemeData(color:Colors.white,elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20)))),home:const Home());}
