 Widget metric(String label,double value,Color color,IconData icon)=>Expanded(child:Row(children:[CircleAvatar(radius:15,backgroundColor:color.withOpacity(.18),child:Icon(icon,color:color,size:16)),const SizedBox(width:8),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:Colors.white70,fontSize:11)),Text(fmt.format(value),maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w700,fontSize:13))]))]));
